//! 🎟️ Original actor input and paid authorities remain in place across admitted turns.
use semio_framework_actor_retained_turn::{RetainedTurnInput,OriginalActorTurnWork};
use semio_framework_async::{CancelToken,CancelTokenRetirement,CancelTokenRetirementError};
use semio_framework_job::{OriginalRetirementPump, Generation, OperationId, OriginalCallerSourceAdmission, OriginalCallerSourceParent, OriginalJobDecodeOwner, OriginalTurnFailure, StepBudget, StepContext};
use semio_framework_job_payload::{JobPayloadAuthority};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetirementDemand,ValueError,ValueRefusalKind};
use std::mem::ManuallyDrop;

pub type OriginalActorAdmissionFailure=OriginalTurnFailure;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct OriginalActorAdmission{pub ready:bool,pub progress:RetainedCloneProgress}
#[derive(Debug,semio_framework_value::RetireOwned)]
pub enum OriginalActorContextError{Refused(ValueError),Cancellation(CancelTokenRetirementError),CancellationReceipt{blocked:semio_framework_async::CancelTokenRetirementBlocked,receipt:OriginalTurnFailure},Original(OriginalTurnFailure)}
impl OriginalActorContextError{
 /// 🧾️ The complete failed child keeps its original physical effects even when receipt validation also refuses.
 pub fn retained_progress(&self)->RetainedCloneProgress{match self{Self::Refused(error)|Self::Cancellation(CancelTokenRetirementError::Refused(error))=>error.retained_progress(),Self::Original(failure)=>failure.retained_progress(),Self::CancellationReceipt{receipt,..}=>receipt.retained_progress(),Self::Cancellation(CancelTokenRetirementError::Blocked(_))=>Default::default()}}
}
/// 🧳️ Owns the same input until dispatch and borrows the same admitted root and payload ledger.
pub struct OriginalActorContext<T>{birth:semio_framework_job_native_turn::OriginalJobReturnBirth,input:ManuallyDrop<Option<T>>,identity:Option<(OperationId,Generation)>,epoch:u64,work:OriginalActorTurnWork,work_units_spent:u128,initial_grant:RetainedCloneGrant,issued_grant:RetainedCloneGrant,fresh_spent:RetainedCloneProgress,epoch_fresh_start:RetainedCloneProgress,reserved_spent:RetainedCloneProgress,reserved_work:u128,clock:Option<fn()->Option<u64>>,cancel:ManuallyDrop<Option<CancelToken>>,payload:ManuallyDrop<Option<JobPayloadAuthority>>,cancel_close:ManuallyDrop<Option<CancelTokenRetirement>>,source:ManuallyDrop<Option<OriginalCallerSourceParent>>,source_admission:OriginalCallerSourceAdmission,decoder:ManuallyDrop<OriginalJobDecodeOwner>,sequence:u64,ready:bool,closing:bool}
#[cfg(test)]
fn fresh_progress(total:RetainedCloneProgress,reserved:RetainedCloneProgress)->Result<RetainedCloneProgress,ValueError>{let e=||refusal("reserved actor effects exceed their actual aggregate");Ok(RetainedCloneProgress{copied_items:total.copied_items.checked_sub(reserved.copied_items).ok_or_else(e)?,copied_bytes:total.copied_bytes.checked_sub(reserved.copied_bytes).ok_or_else(e)?,retained_capacity_bytes:total.retained_capacity_bytes.checked_sub(reserved.retained_capacity_bytes).ok_or_else(e)?,released_bytes:total.released_bytes.checked_sub(reserved.released_bytes).ok_or_else(e)?})}
impl<T> OriginalActorContext<T>{
 pub fn new(input:T,retained:RetainedTurnInput)->Result<Self,(ValueError,T)>{if let Err(error)=retained.validate(){return Err((error,input))}Ok(Self{birth:Default::default(),input:ManuallyDrop::new(Some(input)),identity:Some((OperationId(retained.operation),Generation(retained.generation))),epoch:0,work:retained.work,work_units_spent:0,initial_grant:retained.grant,issued_grant:retained.grant,fresh_spent:Default::default(),epoch_fresh_start:Default::default(),reserved_spent:Default::default(),reserved_work:0,clock:None,cancel:ManuallyDrop::new(None),payload:ManuallyDrop::new(None),cancel_close:ManuallyDrop::new(None),source:ManuallyDrop::new(None),source_admission:OriginalCallerSourceAdmission::new(),decoder:ManuallyDrop::new(OriginalJobDecodeOwner::empty()),sequence:0,ready:false,closing:false})}
 pub fn input(&self)->Option<&T>{self.input.as_ref()}
 pub fn original_work_units_spent(&self)->u128{self.work_units_spent}
 pub fn remaining_work(&self)->Result<OriginalActorTurnWork,ValueError>{let spent=u64::try_from(self.fresh_work()?).map_err(|_|refusal("original actor actual work exceeds u64 source fuel"))?;let fuel=self.work.fuel.checked_sub(spent).ok_or_else(||refusal("original actor actual work exceeds declared total source fuel"))?;Ok(OriginalActorTurnWork{fuel,..self.work})}
 pub fn remaining_grant(&self)->Result<RetainedCloneGrant,ValueError>{let fresh=self.fresh_spent;if !fresh.fits(self.initial_grant){return Err(refusal("original physical receipt exceeds its initial source authority"))}Ok(RetainedCloneGrant{maximum_items:self.initial_grant.maximum_items-fresh.copied_items,maximum_copy_bytes:self.initial_grant.maximum_copy_bytes-fresh.copied_bytes,maximum_capacity_bytes:self.initial_grant.maximum_capacity_bytes-fresh.retained_capacity_bytes,maximum_release_bytes:self.initial_grant.maximum_release_bytes-fresh.released_bytes,maximum_depth:self.initial_grant.maximum_depth})}
 fn fresh_work(&self)->Result<u128,ValueError>{self.work_units_spent.checked_sub(self.reserved_work).ok_or_else(||refusal("reserved actor work exceeds its actual aggregate"))}
 fn record_physical(&mut self,progress:RetainedCloneProgress)->Result<(),ValueError>{self.fresh_spent=self.fresh_spent.checked_add(progress)?;self.remaining_grant()?;Ok(())}
 fn validate_policy(input:RetainedTurnInput,policy:RetainedCloneGrant)->Result<(),ValueError>{if !subset(policy,input.grant){return Err(refusal("original call policy exceeds supplied total authority"))}Ok(())}
 fn permits(grant:semio_framework_value::RetainedCloneGrant,demand:RetirementDemand)->bool{grant.maximum_items!=0&&grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes&&grant.maximum_depth>=demand.depth}
 fn validate_currency(&self,retained:RetainedTurnInput)->Result<(),ValueError>{retained.validate()?;if (retained.epoch==self.epoch&&retained.grant!=self.issued_grant)||(retained.epoch!=self.epoch&&!subset(retained.grant,self.remaining_grant()?)){return Err(refusal("original actor context renewed its physical source authority"))}if (retained.epoch==self.epoch&&retained.work!=self.work)||retained.work.clock_binding!=self.work.clock_binding||retained.work.absolute_deadline_us!=self.work.absolute_deadline_us||(retained.epoch!=self.epoch&&u128::from(retained.work.fuel)>u128::from(self.work.fuel).checked_sub(self.fresh_work()?).ok_or_else(||refusal("original actor work exceeds its total original fuel"))?){return Err(refusal("original actor context changed its issuer clock/deadline or renewed work"))}Ok(())}
 fn validate(&self,retained:RetainedTurnInput)->Result<(),ValueError>{self.validate_currency(retained)?;if self.identity!=Some((OperationId(retained.operation),Generation(retained.generation))){return Err(refusal("original actor context identity differs from supplied input"))}Ok(())}
 fn begin(&mut self,retained:RetainedTurnInput)->Result<(),ValueError>{self.validate(retained)?;if retained.epoch<=self.epoch{return Err(refusal("original actor context turn epoch was already used"))}self.epoch=retained.epoch;self.work=retained.work;self.issued_grant=retained.grant;self.epoch_fresh_start=self.fresh_spent;self.work_units_spent=0;self.reserved_work=0;Ok(())}
 /// 🌱️ One caller-funded root or ledger birth yields before any semantic producer.
 pub fn admit_step(&mut self,retained:RetainedTurnInput,budget:StepBudget,clock:fn()->Option<u64>)->Result<OriginalActorAdmission,OriginalActorAdmissionFailure>{
  Self::validate_policy(retained,budget.retained)?;if budget.fuel>retained.work.fuel||budget.deadline_us>retained.work.absolute_deadline_us{return Err(refusal("admission scope exceeds its original work").into())}
  let mut result=self.admit_inner(retained,budget,clock);let p=match &result{Ok(v)=>v.progress,Err(e)=>e.retained_progress()};
  let posted=self.record_physical(p);if let Err(error)=posted{let mut failure=match result{Err(e)=>{let mut f=OriginalTurnFailure::from(e);f.receipt_refusal=Some(error);f},Ok(_)=>OriginalTurnFailure::from(error)};failure.effects=p;return Err(failure)}
  match result.as_mut(){Ok(v)=>v.progress=p,Err(e)=>{let original=std::mem::replace(e,refusal("admission error moved into its original failure"));*e=original.with_retained_progress(p)}}result.map_err(Into::into)
 }
 fn admit_inner(&mut self,retained:RetainedTurnInput,budget:StepBudget,clock:fn()->Option<u64>)->Result<OriginalActorAdmission,ValueError>{
  let policy=budget.retained;if self.closing{return Err(refusal("original actor context is closing"))}if budget.fuel==0||clock().is_none_or(|now|now>=budget.deadline_us){return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})}if self.clock.is_some_and(|original|!std::ptr::fn_addr_eq(original,clock)){return Err(refusal("original actor admission substituted its issuer clock callback"))}
  let source_birth=self.source.is_none()&&(!self.source_admission.terminal_is_empty()||(self.cancel.is_some()&&self.payload.is_some()));let demand=if self.source.is_some(){RetirementDemand{depth:1,..Default::default()}}else if self.source_admission.terminal_is_empty()&&self.cancel.is_none(){CancelToken::root_admission_demands()}else if self.source_admission.terminal_is_empty()&&self.payload.is_none(){JobPayloadAuthority::admission_demand()}else{Self::source_stage_demand(&self.source_admission)?};let required=if source_birth{Self::source_stage_work(&self.source_admission)}else{1};if required>budget.fuel||!Self::permits(policy,demand){return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})}
  self.begin(retained)?;self.work_units_spent=0;self.clock=Some(clock);
  if self.source.is_none(){if self.source_admission.terminal_is_empty()&&self.cancel.is_none(){let turn=CancelToken::admit_root(policy);self.work_units_spent=u128::from(turn.work);let Some((original,progress))=turn.result?else{return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})};*self.cancel=Some(original);return Ok(OriginalActorAdmission{ready:false,progress})}
   if self.source_admission.terminal_is_empty()&&self.payload.is_none(){let(operation,generation)=self.identity.ok_or_else(||refusal("identity absent"))?;let mut actual=None;let turn=JobPayloadAuthority::admit(operation,generation,policy,&mut actual);self.work_units_spent=u128::from(turn.work);let Some((original,progress))=turn.result?else{return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})};*self.payload=Some(original);return Ok(OriginalActorAdmission{ready:false,progress})}
   let clock=self.clock.ok_or_else(||refusal("original Source birth requires its admitted clock"))?;
   let stage=Self::source_stage(&self.source_admission);let grant=RetainedCloneGrant{maximum_items:policy.maximum_items.min(1),..policy};
   let ran=OriginalRetirementPump::new().turn(budget.fuel,budget.deadline_us,clock,grant).and_then(|mut turn|turn.with_effect(|effect|match stage{
    0=>{let(authority,cancel)=(&mut *self.payload,&mut *self.cancel);self.source_admission.prepare(authority,cancel,effect)},
    1=>self.source_admission.admit_backing(effect),
    _=>self.source_admission.publish(&mut self.source,effect)}))?;
   let Some((turn,work))=ran else{return Ok(OriginalActorAdmission{ready:false,progress:Default::default()})};self.work_units_spent=work;
   return turn.result.map(|step|OriginalActorAdmission{ready:false,progress:step.progress()})
  }self.ready=true;self.work_units_spent=1;Ok(OriginalActorAdmission{ready:true,progress:RetainedCloneProgress{copied_items:1,..Default::default()}})
 }
 /// 🤝️ Lends the persistent original receipt and returns only the actual call delta externally.
 pub fn borrow_context<'a>(&'a mut self,retained:RetainedTurnInput,budget:StepBudget,recipient:&'a mut RetainedCloneProgress,clock:fn()->Option<u64>)->Result<StepContext<'a>,ValueError>{self.validate(retained)?;if !self.ready||self.closing||retained.epoch!=self.epoch||!subset(budget.retained,retained.grant)||u128::from(budget.fuel)>u128::from(retained.work.fuel).checked_sub(self.fresh_work()?).ok_or_else(||refusal("original borrowed work exceeds its original total"))?||budget.deadline_us>retained.work.absolute_deadline_us||self.clock.is_some_and(|original|!std::ptr::fn_addr_eq(original,clock)){return Err(refusal("original actor context loan differs from admitted turn"))}let source=self.source.as_ref().ok_or_else(||refusal("original actor parent source has not been admitted"))?;let total=self.remaining_work()?;let epoch_spent=RetainedCloneProgress{copied_items:self.fresh_spent.copied_items-self.epoch_fresh_start.copied_items,copied_bytes:self.fresh_spent.copied_bytes-self.epoch_fresh_start.copied_bytes,retained_capacity_bytes:self.fresh_spent.retained_capacity_bytes-self.epoch_fresh_start.retained_capacity_bytes,released_bytes:self.fresh_spent.released_bytes-self.epoch_fresh_start.released_bytes};let remaining=retained.return_original(epoch_spent,u64::try_from(self.fresh_work()?).map_err(|_|refusal("original epoch work exceeds u64"))?)?.remaining;let mut cx=source.borrow_context(StepBudget::new(total.fuel,total.absolute_deadline_us,self.initial_grant),clock,&mut self.sequence,&mut self.fresh_spent)?.with_original_decoder(&mut self.decoder);cx.bind_original_source_epoch(retained.epoch)?;cx.bind_original_clock_binding(retained.work.clock_binding)?;cx.bind_original_retained_total(remaining)?;let budget=StepBudget::new(budget.fuel,budget.deadline_us,meet(budget.retained,cx.retained_grant()));cx.narrow_original_work_budget(budget)?;cx.bind_original_physical_recipient(recipient)?;cx.bind_original_work_recipient(&mut self.work_units_spent)?;cx.bind_original_reserved_recipient(&mut self.reserved_spent,&mut self.reserved_work)?;if cx.return_birth_requested(){let birth=&mut self.birth;cx.with_retained_loan(budget.retained,|cx|birth.service(cx).map_err(|failure|ValueError::new(ValueRefusalKind::InvariantViolated,format!("original return birth failed: {failure:?}")).into())).map_err(|failure:OriginalTurnFailure|ValueError::new(ValueRefusalKind::InvariantViolated,format!("original return birth failed: {failure:?}")))?;}Ok(cx)}
 /// ▶️ A dispatched turn borrows already admitted authorities under its next original epoch.
 pub fn begin_dispatch(&mut self,retained:RetainedTurnInput)->Result<(),ValueError>{if !self.ready||self.closing{return Err(refusal("original actor context has not reached paid readiness"))}self.begin(retained)}
 /// 📬️ Moves the original input once into its semantic consumer after both births yielded.
 pub fn take_input(&mut self)->Result<Option<T>,ValueError>{if !self.ready||self.closing||self.source.is_none(){return Err(refusal("original actor input cannot dispatch before paid authorities"))}Ok(self.input.take())}
 pub fn terminal_is_empty(&self)->bool{self.input.is_none()&&self.identity.is_none()&&self.cancel.is_none()&&self.payload.is_none()&&self.cancel_close.is_none()&&self.source.is_none()&&self.source_admission.terminal_is_empty()&&self.decoder.terminal_is_empty()&&self.birth.terminal_is_empty()}
 pub fn original_loans_are_returned(&self)->bool{self.source.as_ref().is_none_or(OriginalCallerSourceParent::original_loans_are_returned)}
 pub fn native_sources_pending(&self)->bool{self.source.as_ref().is_some_and(OriginalCallerSourceParent::native_sources_pending)}
 pub fn native_close_requires_execution(&self)->Option<bool>{self.source.as_ref().map_or(Some(false),OriginalCallerSourceParent::native_close_requires_execution)}
 /// 📏️ Quotes one original physical frontier or one separate enclosing metadata removal.
 pub fn retirement_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.input.is_some(){return Err(refusal("original actor input still requires its semantic owner"))}if !self.decoder.terminal_is_empty(){return self.decoder.retirement_demands(body)}if !self.birth.terminal_is_empty(){return Ok(RetirementDemand{depth:1,..Default::default()})}if let Some(source)=self.source.as_ref(){if !source.terminal_is_empty(){return source.retirement_demands()}return Ok(RetirementDemand{depth:1,..Default::default()})}if let Some(payload)=self.payload.as_ref(){if !payload.terminal_is_empty(){return Ok(payload.retirement_demands())}return Ok(RetirementDemand{depth:1,..Default::default()})}if self.cancel.is_some(){return Ok(RetirementDemand{depth:1,..Default::default()})}if let Some(cancel)=self.cancel_close.as_ref(){if !cancel.terminal_is_empty(){return cancel.retirement_demands()}return Ok(RetirementDemand{depth:1,..Default::default()})}Ok(RetirementDemand{depth:usize::from(self.identity.is_some()),..Default::default()})}
 pub fn retirement_work_demand(&self,body:usize)->Result<u64,ValueError>{self.retirement_demands(body)?;if self.terminal_is_empty(){return Ok(0)}if !self.decoder.terminal_is_empty(){return Err(refusal("decoder retirement work requires its live original context"))}if !self.birth.terminal_is_empty(){return Err(refusal("birth retirement work requires its live original context"))}if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(1)}else{source.retirement_work_demand()}}if let Some(payload)=self.payload.as_ref(){return if payload.terminal_is_empty(){Ok(1)}else{payload.retirement_work_demand()}}if self.cancel.is_some(){return Ok(1)}if let Some(cancel)=self.cancel_close.as_ref(){return if cancel.terminal_is_empty(){Ok(1)}else{Ok(cancel.retirement_work_demand())}}Ok(1)}
 /// ♻️ Each original authority closes before its separate inline removal turn.
 pub fn close_step(&mut self,retained:RetainedTurnInput,budget:StepBudget)->Result<RetainedCloneStep,OriginalActorContextError>{Self::validate_policy(retained,budget.retained).map_err(OriginalActorContextError::Refused)?;if budget.fuel>retained.work.fuel||budget.deadline_us>retained.work.absolute_deadline_us{return Err(OriginalActorContextError::Refused(refusal("actor retirement scope exceeds its original work")))}if !self.decoder.terminal_is_empty(){return self.close_owned(retained,budget,false)}if !self.birth.terminal_is_empty(){return self.close_owned(retained,budget,true)}let result=self.close_inner(retained,budget);let progress=match &result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};let debit=self.record_physical(progress);match(result,debit){(result,Ok(()))=>result,(Ok(_),Err(error))=>Err(OriginalActorContextError::Refused(error.with_retained_progress(progress))),(Err(OriginalActorContextError::Refused(primary)|OriginalActorContextError::Cancellation(CancelTokenRetirementError::Refused(primary))),Err(receipt))=>{let mut failure=OriginalTurnFailure::from(primary);failure.receipt_refusal=Some(receipt);Err(OriginalActorContextError::Original(failure))},(Err(OriginalActorContextError::Original(mut failure)),Err(receipt))=>{failure.context_refusal=Some(receipt);Err(OriginalActorContextError::Original(failure))},(Err(OriginalActorContextError::Cancellation(CancelTokenRetirementError::Blocked(blocked))),Err(receipt))=>{let mut receipt=OriginalTurnFailure::from(receipt);receipt.effects=progress;Err(OriginalActorContextError::CancellationReceipt{blocked,receipt})},(Err(OriginalActorContextError::CancellationReceipt{blocked,mut receipt}),Err(posting))=>{receipt.context_refusal=Some(posting);Err(OriginalActorContextError::CancellationReceipt{blocked,receipt})}}}
 /// ♻️ Closes the decoder or the birth driver under the same Source context bindings, never re-servicing the birth.
 fn close_owned(&mut self,input:RetainedTurnInput,budget:StepBudget,birth:bool)->Result<RetainedCloneStep,OriginalActorContextError>{
  let policy=budget.retained;let policy=RetainedCloneGrant{maximum_items:policy.maximum_items.min(1),..policy};
  self.validate(input).map_err(OriginalActorContextError::Refused)?;let demand=self.retirement_demands(policy.maximum_copy_bytes).map_err(OriginalActorContextError::Refused)?;if budget.fuel==0||!Self::permits(policy,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}
  let mut physical=RetainedCloneProgress::default();
  let result=(||->Result<(),OriginalTurnFailure>{self.validate(input)?;if self.input.is_some(){return Err(refusal("original actor input still requires its semantic owner").into())}self.begin(input)?;let remaining=self.remaining_grant()?;let work=self.remaining_work()?;let clock=self.clock.ok_or_else(||refusal("original decoder close requires its admitted clock"))?;let source=self.source.as_ref().ok_or_else(||refusal("original decoder close requires its admitted Source"))?;let budget=StepBudget::new(budget.fuel,budget.deadline_us,policy);let mut cx=source.borrow_context(StepBudget::new(work.fuel,work.absolute_deadline_us,self.initial_grant),clock,&mut self.sequence,&mut self.fresh_spent)?;cx.bind_original_source_epoch(input.epoch)?;cx.bind_original_clock_binding(input.work.clock_binding)?;cx.bind_original_retained_total(remaining)?;let budget=StepBudget::new(budget.fuel,budget.deadline_us,meet(budget.retained,cx.retained_grant()));cx.narrow_original_work_budget(budget)?;cx.bind_original_physical_recipient(&mut physical)?;cx.bind_original_work_recipient(&mut self.work_units_spent)?;cx.bind_original_reserved_recipient(&mut self.reserved_spent,&mut self.reserved_work)?;cx.with_original_retirement(|cx|if birth{self.birth.close_step(cx).map(|_|())}else{self.decoder.close_on_source(cx).map(|_|())})})();
  if self.work_units_spent!=0{self.closing=true}result.map(|()|RetainedCloneStep::Progress(physical)).map_err(OriginalActorContextError::Original)
 }
 fn close_inner(&mut self,retained:RetainedTurnInput,budget:StepBudget)->Result<RetainedCloneStep,OriginalActorContextError>{let policy=budget.retained;
  if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}
  self.validate(retained).map_err(OriginalActorContextError::Refused)?;
  let demand=self.retirement_demands(policy.maximum_copy_bytes).map_err(OriginalActorContextError::Refused)?;
  let grant=RetainedCloneGrant{maximum_items:policy.maximum_items.min(1),..policy};let required=self.retirement_work_demand(policy.maximum_copy_bytes).map_err(OriginalActorContextError::Refused)?;
  if budget.fuel==0||required>budget.fuel||!Self::permits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}
  self.begin(retained).map_err(OriginalActorContextError::Refused)?;
  if let Some(source)=self.source.as_mut(){
   if !source.terminal_is_empty(){let clock=self.clock.ok_or_else(||OriginalActorContextError::Refused(refusal("original Source close requires its admitted clock")))?;let Some((poll,work))=OriginalRetirementPump::new().turn(budget.fuel,budget.deadline_us,clock,grant).and_then(|mut turn|turn.with_effect(|effect|source.close_step(effect))).map_err(OriginalActorContextError::Refused)? else{return Ok(RetainedCloneStep::Progress(Default::default()))};self.record_close_work(work);return match poll{semio_framework_value::RetainedWorkPoll::Complete(turn)=>turn.result.map(|step|RetainedCloneStep::Progress(step.progress())).map_err(|failure|OriginalActorContextError::Original(failure.into())),semio_framework_value::RetainedWorkPoll::Pending{..}=>Ok(RetainedCloneStep::Progress(Default::default()))}}
   self.record_close_work(1);drop(self.source.take());return Ok(metadata(false))
  }
  if let Some(payload)=self.payload.as_mut(){
   if !payload.terminal_is_empty(){let clock=self.clock.ok_or_else(||OriginalActorContextError::Refused(refusal("original payload close requires its admitted clock")))?;let Some((turn,work))=OriginalRetirementPump::new().turn(budget.fuel,budget.deadline_us,clock,grant).and_then(|mut turn|turn.with_effect(|effect|payload.close_step(effect))).map_err(OriginalActorContextError::Refused)? else{return Ok(RetainedCloneStep::Progress(Default::default()))};self.record_close_work(work);return turn.result.map(|step|RetainedCloneStep::Progress(step.progress())).map_err(OriginalActorContextError::Refused)}
   self.record_close_work(1);drop(self.payload.take());return Ok(metadata(false))
  }
  if let Some(cancel)=self.cancel.take(){self.record_close_work(1);*self.cancel_close=Some(CancelTokenRetirement::from_token(cancel));return Ok(metadata(false))}
  if let Some(cancel)=self.cancel_close.as_mut(){
   if !cancel.terminal_is_empty(){let clock=self.clock.ok_or_else(||OriginalActorContextError::Refused(refusal("original cancellation close requires its admitted clock")))?;let Some((turn,work))=OriginalRetirementPump::new().turn(budget.fuel,budget.deadline_us,clock,grant).and_then(|mut turn|turn.with_effect(|effect|cancel.close_step(effect))).map_err(OriginalActorContextError::Refused)? else{return Ok(RetainedCloneStep::Progress(Default::default()))};self.record_close_work(work);return turn.result.map(|step|RetainedCloneStep::Progress(step.progress())).map_err(OriginalActorContextError::Cancellation)}
   self.record_close_work(1);drop(self.cancel_close.take());return Ok(metadata(false))
  }
  self.record_close_work(1);self.identity=None;Ok(metadata(true))
 }
 fn source_stage(admission:&OriginalCallerSourceAdmission)->u8{if admission.has_backing(){2}else if admission.has_roots(){1}else{0}}
 fn source_stage_demand(admission:&OriginalCallerSourceAdmission)->Result<RetirementDemand,ValueError>{match Self::source_stage(admission){0=>Ok(OriginalCallerSourceAdmission::prepare_demand()),1=>OriginalCallerSourceAdmission::backing_demand(),_=>Ok(OriginalCallerSourceAdmission::publish_demand())}}
 fn source_stage_work(admission:&OriginalCallerSourceAdmission)->u64{match Self::source_stage(admission){1=>OriginalCallerSourceAdmission::backing_work_demand(),_=>1}}
 fn record_close_work(&mut self,work:u128){self.work_units_spent=work;if work!=0{self.closing=true}}

}
fn meet(a:RetainedCloneGrant,b:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:a.maximum_items.min(b.maximum_items),maximum_copy_bytes:a.maximum_copy_bytes.min(b.maximum_copy_bytes),maximum_capacity_bytes:a.maximum_capacity_bytes.min(b.maximum_capacity_bytes),maximum_release_bytes:a.maximum_release_bytes.min(b.maximum_release_bytes),maximum_depth:a.maximum_depth.min(b.maximum_depth)}}
fn subset(a:RetainedCloneGrant,b:RetainedCloneGrant)->bool{a.maximum_items<=b.maximum_items&&a.maximum_copy_bytes<=b.maximum_copy_bytes&&a.maximum_capacity_bytes<=b.maximum_capacity_bytes&&a.maximum_release_bytes<=b.maximum_release_bytes&&a.maximum_depth<=b.maximum_depth}
fn metadata(complete:bool)->RetainedCloneStep{let progress=RetainedCloneProgress{copied_items:1,..Default::default()};if complete{RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)}}
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl<T> Drop for OriginalActorContext<T>{fn drop(&mut self){assert!(self.terminal_is_empty(),"original actor context reached Drop before paid authority retirement");}}

