/// 🪪️ A nominal capture origin seals an actual failed native call without granting another Source or job.
pub struct OriginalActorFailureCall<I:Copy>{_origin:I,reference:semio_framework_actor_failure::ActorFailureCallReference,producer:semio_framework_job::OriginalNativeRecipientIdentity,binding:semio_framework_job::OriginalSourceBinding}
impl<I:Copy> OriginalActorFailureCall<I>{
 pub fn captured_by(origin:I,reference:semio_framework_actor_failure::ActorFailureCallReference,producer:semio_framework_job::OriginalNativeRecipientIdentity,cx:&StepContext<'_>)->Result<Self,OriginalTurnFailure>{reference.validate()?;producer.validate_context(cx)?;Ok(Self{_origin:origin,reference,producer,binding:semio_framework_job::OriginalSourceBinding::borrow(cx)})}
 pub fn reference_for(&self,producer:semio_framework_job::OriginalNativeRecipientIdentity,cx:&StepContext<'_>)->Result<semio_framework_actor_failure::ActorFailureCallReference,OriginalTurnFailure>{producer.validate_context(cx)?;if self.producer!=producer||!self.binding.matches(cx){return Err(ValueError::invariant("actor failure reference changed its actual native producer").into())}Ok(self.reference)}
}

/// ♻️ Closes an actual retained slot through its genuine actor Source and full work receipt.
pub fn close_retained_source_slot<T:semio_framework_value::RetireOwned>(source:&mut Option<T>,retirement:&mut Option<semio_framework_value::retirement::controlled::ControlledRetirement<T>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
 cx.original_source_parent()?.validate_borrowed_context(cx)?;
 if source.is_none()&&retirement.is_none(){return Ok(true)}
 if let Some(owner)=retirement.as_mut(){if !owner.terminal_is_empty(){let bytes=cx.retained_grant().maximum_copy_bytes;let demand=owner.next_demand(bytes)?;let work=owner.next_computational_work(bytes)?;if work>cx.fuel_remaining(){return Ok(false)}semio_framework_job::close_original_effect_step(cx,demand,|effect|owner.step(bytes,effect))?;return Ok(false)}}
 let capture=retirement.is_none();let items=1;let work=if capture{2}else{1};let bytes=std::mem::size_of_val(retirement)+if capture{std::mem::size_of_val(source)}else{0};let progress=RetainedCloneProgress{copied_items:items,copied_bytes:bytes,..Default::default()};if cx.retirement_should_yield()||cx.fuel_remaining()<work||cx.retained_grant().maximum_depth==0||!progress.fits(cx.retained_grant()){return Ok(false)}cx.retained_progress().checked_add(progress)?;
 if capture{*retirement=Some(semio_framework_value::retirement::controlled::ControlledRetirement::retain(source.take().ok_or_else(||refusal("Source close keeps its original owner"))?))}else{retirement.take();}let posted=cx.consume_retained(progress);cx.consume_fuel(work);posted?;Ok(source.is_none()&&retirement.is_none())
}

